import math


def wilson_interval(successes: int, total: int, z: float = 1.96) -> tuple[float, float, float]:
    if total <= 0:
        raise ValueError("total must be positive")
    if successes < 0 or successes > total:
        raise ValueError("successes must lie in [0, total]")
    if not math.isfinite(z) or z <= 0:
        raise ValueError("z must be finite and positive")

    estimate = successes / total
    denominator = 1.0 + z * z / total
    center = (estimate + z * z / (2.0 * total)) / denominator
    half_width = z / denominator * math.sqrt(
        estimate * (1.0 - estimate) / total + z * z / (4.0 * total * total)
    )
    return estimate, max(0.0, center - half_width), min(1.0, center + half_width)


def worst_case_sample_size(margin: float, z: float = 1.96) -> int:
    if not math.isfinite(margin) or not 0.0 < margin < 1.0:
        raise ValueError("margin must lie in (0, 1)")
    if not math.isfinite(z) or z <= 0:
        raise ValueError("z must be finite and positive")
    return math.ceil(z * z / (4.0 * margin * margin))
```

The Wilson interval remains non-degenerate at $0/n$ and $n/n$, unlike the symmetric Wald interval. Clipping the endpoints only protects against tiny rounding excursions outside $[0,1]$.

