def pass_at_k(n: int, c: int, k: int) -> float:
    if n <= 0 or not 0 <= c <= n or not 1 <= k <= n:
        raise ValueError("require n>0, 0<=c<=n, and 1<=k<=n")
    if n - c < k:
        return 1.0
    probability_of_miss = 1.0
    for i in range(k):
        probability_of_miss *= (n - c - i) / (n - i)
    return 1.0 - probability_of_miss


def coverage_and_selection(correct, selected_index: int) -> tuple[bool, bool]:
    values = [bool(x) for x in correct]
    if not values or not 0 <= selected_index < len(values):
        raise ValueError("invalid candidate pool or selected index")
    return any(values), values[selected_index]
```

