from __future__ import annotations


def ngram_set(text: str, n: int) -> set[tuple[str, ...]]:
    if n <= 0:
        raise ValueError("n must be positive")
    tokens = text.casefold().split()
    return {tuple(tokens[i : i + n]) for i in range(len(tokens) - n + 1)}


def ngram_containment(benchmark_text: str, corpus_text: str, n: int) -> float:
    benchmark = ngram_set(benchmark_text, n)
    corpus = ngram_set(corpus_text, n)
    if not benchmark:
        return 0.0
    return len(benchmark & corpus) / len(benchmark)


def ngram_jaccard(left: str, right: str, n: int) -> float:
    a = ngram_set(left, n)
    b = ngram_set(right, n)
    union = a | b
    return 0.0 if not union else len(a & b) / len(union)


def contamination_report(items, corpus, *, n=8, threshold=0.2):
    if not 0.0 <= threshold <= 1.0:
        raise ValueError("threshold must lie in [0, 1]")
    maxima = []
    matches = []
    for i, item in enumerate(items):
        scores = [ngram_containment(item, doc, n) for doc in corpus]
        best = max(scores, default=0.0)
        maxima.append(best)
        for j, score in enumerate(scores):
            if score >= threshold:
                matches.append((i, j, score))
    return {
        "metric": "benchmark_ngram_containment",
        "n": n,
        "threshold": threshold,
        "max_overlap": maxima,
        "matches": matches,
    }


assert ngram_containment("a b c", "x a b c y", 2) == 1.0
assert ngram_jaccard("a b c", "x a b c y", 2) == 0.5
```

Containment divides by benchmark-item n-grams; Jaccard divides by the union. The report stores the metric name so downstream code cannot silently conflate them.

